#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> H(N), leftMax(N), rightMax(N);
    for (auto& h : H) cin >> h;

    leftMax[0] = H[0];
    for (int i = 1; i < N; ++i)
        leftMax[i] = max(leftMax[i - 1], H[i]);

    rightMax[N - 1] = H[N - 1];
    for (int i = N - 2; i >= 0; --i)
        rightMax[i] = max(rightMax[i + 1], H[i]);

    int answer = 0;
    for (int i = 0; i < N; ++i) {
        long long waterLevel = min(leftMax[i], rightMax[i]);
        if (waterLevel - H[i] >= 1)
            ++answer;
    }

    cout << answer << '\n';
    return 0;
}
